<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {watchHostTheme} from './theme.js'
const props=defineProps({api:Object,pluginId:{type:String,default:'ForumSignin'},show_switch:{type:Boolean,default:true}})
const emit=defineEmits(['close','switch','layout'])
const stats=ref(null),history=ref({total:0,items:[]}),error=ref(''),busy=ref(false)
const labels={success:'成功',signed:'已签',failed:'失败',auth_failed:'认证失败',unconfirmed:'未确认',network_error:'网络异常',skipped:'未进行',disabled:'未进行'}
const stateClass=s=>['success','signed'].includes(s)?'success':['failed','auth_failed'].includes(s)?'failure':['unconfirmed','network_error'].includes(s)?'unknown':'off'
function formatTime(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return v;return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}:${String(d.getSeconds()).padStart(2,'0')}`}
async function get(path){const r=await props.api.get(`plugin/${props.pluginId}/${path}`);if(r?.success===false)throw Error(r.message);return r?.data??r}
async function loadHistory(){const first=await get('history?page=1&size=100');const items=[...(first.items||[])];for(let page=2;items.length<first.total;page++){const next=await get(`history?page=${page}&size=100`);if(!next.items?.length)break;items.push(...next.items)}return {total:first.total,items}}
async function load(){error.value='';try{[stats.value,history.value]=await Promise.all([get('stats'),loadHistory()])}catch(e){error.value=e.message||'加载失败'}}
function attributes(info){const attrs=info?.data?.attributes;return attrs&&typeof attrs==='object'?attrs:(info||{})}
function streak(site){if(site.id==='fengchao'){const value=attributes(stats.value?.fengchao_user_info).totalContinuousCheckIn;if(value!==undefined&&value!==null)return value}const rows=history.value.items.filter(x=>x.site===site.id).sort((a,b)=>new Date(b.time)-new Date(a.time));if(!rows.length)return 0;let latestDay='',n=0;for(const row of rows){if(!['success','signed','already'].includes(row.status))break;const day=formatTime(row.time).slice(0,10);if(day!==latestDay){n++;latestDay=day}}return n}
function syncInfo(){return attributes(stats.value?.fengchao_user_info)}
function hasSyncInfo(){const info=stats.value?.fengchao_user_info;return !!(info?.data?.attributes||info)&&Object.keys(syncInfo()).length>0}
function syncStatus(){const sync=stats.value?.fengchao_sync;if(!sync)return '';return sync.success?`上次同步：${formatTime(sync.time)}`:`同步失败：${sync.message||'结果未确认'}`}
async function action(path){busy.value=true;error.value='';try{const r=await props.api.post(`plugin/${props.pluginId}/${path}`,{auth:'bear'});if(r?.success===false)throw Error(r.message);await load()}catch(e){error.value=e.message||'执行失败'}finally{busy.value=false}}
let stopTheme;onMounted(()=>{stopTheme=watchHostTheme();load();emit('layout',{maxWidth:'1000px'})});onBeforeUnmount(()=>stopTheme?.())
</script>
<template><div class="pt-center"><section class="card embedded-card" aria-label="论坛签到数据"><div class="card-head"><h2>论坛签到</h2><div class="row"><button v-if="show_switch" class="btn ghost" @click="emit('switch')">配置</button><button class="btn ghost" @click="emit('close')">关闭</button></div></div><div v-if="error" class="alert" role="alert">{{error}}</div><div v-if="stats" class="win"><div class="topline"><h3>论坛签到</h3><div class="row"><span class="hint">下次调度：{{formatTime(stats.next_schedule)||'未设置'}}</span><button class="btn ghost" :disabled="busy" aria-label="刷新" @click="load">⟳ 刷新</button><button class="btn" :disabled="busy" @click="action('run_once')">立即运行</button></div></div><div class="data-grid"><article v-for="site in stats.sites||[]" :key="site.id" class="site-card fcard"><div class="site-head"><strong class="site-label"><img v-if="site.icon" class="site-icon" :src="site.icon" alt=""><span v-else class="site-icon site-initial">{{site.name?.slice(0,1)}}</span>{{site.name}}</strong><span class="chip" :class="stateClass(site.status)">{{labels[site.status]||'未进行'}}</span></div><p class="meta">连续签到 {{streak(site)}} 天</p><template v-if="site.id==='fengchao'"><p v-if="hasSyncInfo()" class="meta">{{syncInfo().displayName||'蜂巢用户'}} · 大洋 {{syncInfo().money??syncInfo().points??'—'}} · 连续签到 {{syncInfo().totalContinuousCheckIn??'—'}} 天 · 最长 {{syncInfo().maxCheckInStreak??'—'}} 天 · {{syncInfo().levelName||'—'}} · 本次奖励 {{syncInfo().lastCheckinMoney??'—'}}</p><p v-if="syncStatus()" class="meta">{{syncStatus()}}</p></template><div class="row"><button class="btn ghost mini" :disabled="busy" @click="action('signin_by_domain?domain='+encodeURIComponent(site.domain))">签到</button><button v-if="site.can_sync" class="btn ghost mini" :disabled="busy" @click="action('update_info?domain='+encodeURIComponent(site.domain))">同步数据</button></div><p v-if="site.message" class="meta">{{site.message}}</p></article></div><h3>历史记录</h3><div class="table-wrap"><table><thead><tr><th>时间</th><th>论坛</th><th>状态</th><th>消息</th></tr></thead><tbody><tr v-for="item in history.items" :key="item.time+item.site"><td>{{formatTime(item.time)}}</td><td>{{item.site}}</td><td><span class="chip" :class="stateClass(item.status)">{{labels[item.status]||item.status}}</span></td><td>{{[item.message,item.reward?.reported].filter(Boolean).join(' / ')}}</td></tr></tbody></table><div v-if="!history.items.length" class="empty">暂无历史记录</div></div></div></section></div></template>
<style scoped src="./preview.css"></style>
